# Check girth
def girth(graph, n):
    adj = [[] for _ in range(n)]
    for u,v in graph:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]
        for node in queue:
            for nb in adj[node]:
                if dist[nb] == -1:
                    dist[nb] = dist[node] + 1
                    parent[nb] = node
                    queue.append(nb)
                elif nb != parent[node]:
                    cycle_len = dist[node] + dist[nb] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

def is_5_colorable(graph, n):
    adj = [[] for _ in range(n)]
    for u,v in graph:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(idx):
        if idx == n:
            return True
        used = set()
        for nb in adj[idx]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(5):
            if c not in used:
                colors[idx] = c
                if backtrack(idx + 1):
                    return True
                colors[idx] = -1
        return False

    return backtrack(0)

