    adj = [[] for _ in range(n)]
    for u,v in graph:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(idx):
        if idx == n:
            return True
        used = set()
        for nb in adj[idx]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(5):
            if c not in used:
                colors[idx] = c
                if backtrack(idx + 1):
                    return True
                colors[idx] = -1
        return False

    backtrack(0)
    return colors

